<template><div><header class="page-head"><div><div class="eyebrow">持仓穿透 / {{code}}</div><h1>底层资产</h1><p>行业 → 个股 → 实时涨跌贡献</p></div></header><section class="detail-grid"><div class="glass contributors"><h3>行业配置</h3><div v-for="x in industries" :key="x.industry_name" class="alloc"><div><b>{{x.industry_name}}</b><small>{{x.weight}}%</small></div><div class="alloc-bar"><i :style="{width:x.weight+'%'}"></i></div><span>{{x.change_pct>=0?'+':''}}{{x.change_pct}}%</span></div></div><div class="glass contributors"><h3>前十大重仓实时</h3><div v-for="x in stocks" :key="x.stock_code" class="contrib"><div><b>{{x.stock_name}}</b><small>{{x.weight}}%</small></div><span :class="x.change_pct>=0?'up':'down'">{{x.change_pct>=0?'+':''}}{{x.change_pct}}%</span></div></div></section></div></template><script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{getJSON}from'../api';const code=useRoute().params.code,industries=ref([]),stocks=ref([]);onMounted(async()=>{const[a,b]=await Promise.all([getJSON('/funds/'+code+'/industries'),getJSON('/funds/'+code+'/top-stocks')]);industries.value=a.data.industries;stocks.value=b.data.stocks})</script>
